// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/stats/memory", wrapper.GetMemoryStats)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/stats/torrents/{hash}", wrapper.GetTorrentStats)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/system/health", wrapper.HealthCheck)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/system/info", wrapper.GetSystemInfo)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/system/logs", wrapper.GetLogs)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/system/metrics", wrapper.GetSystemMetrics)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/playlist", wrapper.GetPlaylist)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/settings", wrapper.GetSettings)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v1/settings", wrapper.UpdateSettings)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/stream/{hash}", wrapper.GetStream)
	})
	r.Group(func(r chi.Router) {
		r.Head(options.BaseURL+"/api/v1/stream/{hash}", wrapper.HeadStream)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/tokens", wrapper.CreateToken)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/torrents", wrapper.ListTorrents)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/torrents", wrapper.AddTorrent)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/torrents/backup", wrapper.BackupTorrents)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/torrents/restore", wrapper.RestoreTorrents)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v1/torrents/{hash}", wrapper.DeleteTorrent)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/torrents/{hash}", wrapper.GetTorrent)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v1/torrents/{hash}", wrapper.UpdateTorrent)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v1/torrents/{hash}/preload", wrapper.DeleteTorrentPreload)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/torrents/{hash}/preload", wrapper.GetTorrentPreload)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/torrents/{hash}/preload", wrapper.PutTorrentPreload)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v2/torrents/add", wrapper.QBittorrentAddTorrent)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/cache", wrapper.TSCache)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/echo", wrapper.TSEcho)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/oauth/token", wrapper.GetToken)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/play/{hash}/{index}", wrapper.TSPlay)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/settings", wrapper.TSSettings)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/stream/{filename}", wrapper.TSStream)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/torrent/upload", wrapper.TSTorrentUpload)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/torrents", wrapper.TSTorrents)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/viewed", wrapper.TSViewed)
	})

	return r
}

